import heapq

def solve(data):
    nums = data['nums']
    k = data['k']

    # Use a min heap to keep track of the top k elements
    min_heap = []

    for num in nums:
        if len(min_heap) < k:
            heapq.heappush(min_heap, num)
        elif num > min_heap[0]:
            heapq.heappop(min_heap)
            heapq.heappush(min_heap, num)

    return min_heap[0]

